import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';

/// The branding images are generated by tool/generate_branding_test.dart and
/// feed the launcher icon and splash screen; make sure they exist and have the
/// sizes those tools expect.
void main() {
  const expected = {
    'icon.png': 1024,
    'icon_background.png': 1024,
    'icon_foreground.png': 1024,
    'splash_logo.png': 768,
    'splash_logo_android12.png': 1152,
    'logo.png': 256,
  };

  expected.forEach((name, size) {
    test('assets/branding/$name is a ${size}x$size PNG', () {
      final file = File('assets/branding/$name');
      expect(file.existsSync(), isTrue, reason: '$name is missing');

      final bytes = file.readAsBytesSync();
      expect(
        bytes.sublist(0, 8),
        [0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A],
        reason: 'PNG signature',
      );
      final header = ByteData.sublistView(bytes);
      expect(header.getUint32(16), size, reason: 'width');
      expect(header.getUint32(20), size, reason: 'height');
    });
  });

  test('the generated platform launcher icons and splash exist', () {
    for (final path in [
      'android/app/src/main/res/mipmap-xxxhdpi/ic_launcher.png',
      'android/app/src/main/res/mipmap-anydpi-v26/ic_launcher.xml',
      'android/app/src/main/res/values-v31/styles.xml',
    ]) {
      expect(File(path).existsSync(), isTrue, reason: '$path is missing');
    }
  });
}
